def vs(sp_t,sp_u,a1t,a1u,a2t,a2u,mt,mu,rt,ru,lt=None,lu=None):
    def w(a,b,low=True):
        x=float(a.replace('$','').replace(',','').split()[0]);y=float(b.replace('$','').replace(',','').split()[0])
        return 'even' if x==y else (('us' if y<x else 'them') if low else ('us' if y>x else 'them'))
    rows=[['Special',sp_t,sp_u,'ask'],['1 bed average',a1t,a1u,w(a1t,a1u)],['2 bed average',a2t,a2u,w(a2t,a2u)],['Move in cost',mt,mu,w(mt,mu)]]
    if rt!='Not in data': rows.append(['Review site rating',rt,ru,w(rt,ru,False)])
    else: rows.append(['Review site rating',rt,ru,'ask'])
    if lt: rows.append(['Leases a week',lt,lu,w(lt,lu,False)])
    return rows
